const CACHE='hk-pocket-v2-504d11596817';
const FILES=["./","./app.js","./data.js","./guide.js","./icon.svg","./index.html","./legacy-v1.js","./manifest.webmanifest","./maps/hong-kong.png","./maps/kowloon.png","./maps/sai-ying-pun.png","./maps/sources.json","./maps/west-kowloon-area.png","./maps/west-kowloon-b2.png","./migration.js","./photos/ferry.jpg","./photos/kong.jpg","./photos/kwan.jpg","./photos/mak.jpg","./photos/park.jpg","./photos/pier.jpg","./photos/statue.jpg","./photos/tai-sign.jpg","./photos/tai.jpg","./photos/taikwun.jpg","./photos/temple.jpg","./photos/tsim.jpg","./photos/tst.jpg","./photos/wah.jpg","./place-content.js","./style.css"];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)));self.skipWaiting();});
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('hk-pocket-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(event.request,copy)));}return response;}).catch(()=>caches.match(event.request).then(cached=>cached||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
